// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "./AscensionJobMarket.sol";

/// @notice MARK's reversible linear-curve AMM becomes a plan-restricted Sovereign treasury at bloom.
contract AscensionMark is AscensionToken, ReentrancyGuard {
    using SafeERC20 for IERC20;
    enum Phase { None, Funding, Bloomed, Closed }
    struct Campaign {
        address business;
        uint96 base;
        uint96 slope;
        uint96 target;
        uint32 maxLots;
        uint32 supply;
        uint32 posted;
        uint32 active;
        uint32 duration;
        uint64 fundingEnd;
        uint64 executionEnd;
        uint256 reserve;
        Phase phase;
        bytes32 businessNode;
    }
    NovaSeed public immutable seed;
    AscensionAccess public immutable access;
    AscensionRiskOracle public immutable oracle;
    AscensionJobMarket public immutable jobs;
    mapping(uint256 => Campaign) public campaigns;
    mapping(uint256 => mapping(address => uint256)) public lots;
    mapping(uint256 => mapping(uint32 => bool)) public posted;
    mapping(uint256 => uint256) public jobSeed;
    mapping(uint256 => bool) public collected;
    event MarketOpened(uint256 indexed id, address indexed business, uint96 base, uint96 slope, uint96 target);
    event Traded(uint256 indexed id, address indexed account, bool buy, uint32 lots, uint256 value);
    event LotsTransferred(uint256 indexed id, address indexed from, address indexed to, uint32 count);
    event Bloomed(uint256 indexed id, bytes32 indexed businessNode, bytes32 planRoot, uint256 funding);
    event MissionRouted(uint256 indexed id, uint32 indexed index, uint256 indexed jobId, bytes32 leaf);
    event MissionCollected(uint256 indexed id, uint256 indexed jobId, uint256 refund);
    event CampaignClosed(uint256 indexed id, uint256 unused, uint32 supply);
    event CapitalReturned(uint256 indexed id, address indexed account, uint256 amount);

    constructor(NovaSeed seed_, AscensionAccess access_, AscensionRiskOracle oracle_, AscensionJobMarket jobs_) {
        require(address(seed_.access()) == address(access_) && address(oracle_.access()) == address(access_) &&
            address(jobs_.access()) == address(access_) && address(oracle_.seed()) == address(seed_) &&
            address(jobs_.oracle()) == address(oracle_), "protocol graph mismatch");
        seed = seed_; access = access_; oracle = oracle_; jobs = jobs_;
    }
    function open(uint256 id, uint96 base, uint96 slope, uint32 maxLots, uint96 target,
        uint64 fundingEnd, uint32 duration) external {
        require(seed.ownerOf(id) == msg.sender && oracle.green(id), "green seed owner required");
        require(campaigns[id].phase == Phase.None && base > 0 && maxLots > 0 && maxLots <= 1000000, "market bounds");
        require(target > 0 && target <= quote(0, maxLots, base, slope), "unreachable target");
        require(fundingEnd > block.timestamp && fundingEnd <= block.timestamp + 30 days &&
            duration > jobs.REVIEW_WINDOW() && duration <= 90 days, "time bounds");
        Campaign storage c = campaigns[id];
        c.business = msg.sender; c.base = base; c.slope = slope; c.target = target; c.maxLots = maxLots;
        c.fundingEnd = fundingEnd; c.duration = duration; c.phase = Phase.Funding;
        c.businessNode = access.names(msg.sender, AscensionAccess.Role.Business);
        emit MarketOpened(id, msg.sender, base, slope, target);
    }
    function quote(uint32 supply, uint32 count, uint96 base, uint96 slope) public pure returns (uint256) {
        require(uint256(supply) + count <= 1000000, "lot bound");
        return uint256(count) * base + uint256(slope) * count * (2 * uint256(supply) + count - (count > 0 ? 1 : 0)) / 2;
    }
    function buy(uint256 id, uint32 count, uint256 maxCost) external nonReentrant {
        Campaign storage c = campaigns[id];
        require(c.phase == Phase.Funding && block.timestamp < c.fundingEnd, "funding closed");
        require(access.admitted(msg.sender) && oracle.green(id) && seed.ownerOf(id) == c.business, "admission gate");
        require(count > 0 && uint256(c.supply) + count <= c.maxLots, "lot bound");
        uint256 cost = quote(c.supply, count, c.base, c.slope);
        require(cost <= maxCost, "slippage");
        _receive(msg.sender, cost); c.supply += count; c.reserve += cost; lots[id][msg.sender] += count;
        emit Traded(id, msg.sender, true, count, cost);
    }
    function sell(uint256 id, uint32 count, uint256 minReturn) external nonReentrant {
        Campaign storage c = campaigns[id];
        // Revoked admission or expired risk never prevents withdrawing unused funding.
        require(c.phase == Phase.Funding && count > 0 && lots[id][msg.sender] >= count, "not redeemable");
        uint256 value = quote(c.supply - count, count, c.base, c.slope);
        require(value >= minReturn, "slippage");
        c.supply -= count; c.reserve -= value; lots[id][msg.sender] -= count;
        token.safeTransfer(msg.sender, value); emit Traded(id, msg.sender, false, count, value);
    }
    function transferLots(uint256 id, address to, uint32 count) external {
        Campaign storage c = campaigns[id];
        require(c.phase == Phase.Funding && block.timestamp < c.fundingEnd && oracle.green(id) &&
            seed.ownerOf(id) == c.business, "funding closed");
        require(access.admitted(msg.sender) && access.admitted(to) && to != address(0), "admission gate");
        require(count > 0 && lots[id][msg.sender] >= count, "insufficient lots");
        lots[id][msg.sender] -= count; lots[id][to] += count;
        emit LotsTransferred(id, msg.sender, to, count);
    }
    function bloom(uint256 id) external {
        Campaign storage c = campaigns[id];
        require(c.phase == Phase.Funding && block.timestamp < c.fundingEnd && c.reserve >= c.target, "not funded");
        require(msg.sender == c.business && seed.ownerOf(id) == c.business && oracle.green(id), "green business required");
        require(access.owns(c.business, c.businessNode), "business ENS changed");
        c.phase = Phase.Bloomed; c.executionEnd = uint64(block.timestamp + c.duration);
        (bytes32 root,) = seed.plan(id);
        emit Bloomed(id, c.businessNode, root, c.reserve);
    }
    function route(uint256 id, uint32 index, AscensionJobMarket.Spec calldata spec, bytes32[] calldata proof,
        uint32 auctionSeconds, address[3] calldata validators) external nonReentrant returns (uint256 jobId) {
        Campaign storage c = campaigns[id];
        require(c.phase == Phase.Bloomed && msg.sender == c.business && access.owns(msg.sender, c.businessNode), "business authority");
        require(seed.ownerOf(id) == c.business && oracle.green(id), "green business required");
        require(block.timestamp + auctionSeconds + spec.duration + jobs.REVIEW_WINDOW() <= c.executionEnd, "execution horizon");
        (bytes32 root, uint32 count) = seed.plan(id);
        bytes32 leaf = jobs.hashSpec(index, spec);
        require(index < count && !posted[id][index] && MerkleProof.verify(proof, root, leaf), "FusionPlan proof");
        require(c.reserve >= spec.bounty, "treasury budget");
        posted[id][index] = true; c.posted++; c.active++; c.reserve -= spec.bounty;
        token.forceApprove(address(jobs), spec.bounty);
        jobId = jobs.postFromSeed(c.business, spec, auctionSeconds, validators);
        token.forceApprove(address(jobs), 0);
        jobSeed[jobId] = id;
        emit MissionRouted(id, index, jobId, leaf);
    }
    function collect(uint256 jobId) external nonReentrant {
        uint256 id = jobSeed[jobId];
        require(id != 0 && !collected[jobId] && jobs.terminal(jobId), "not collectible");
        collected[jobId] = true;
        Campaign storage c = campaigns[id]; c.active--;
        uint256 amount = jobs.claimRefund(jobId); c.reserve += amount;
        emit MissionCollected(id, jobId, amount);
    }
    function close(uint256 id) external {
        Campaign storage c = campaigns[id];
        (, uint32 count) = seed.plan(id);
        if (c.phase == Phase.Funding) require(block.timestamp >= c.fundingEnd, "funding still open");
        else require(c.phase == Phase.Bloomed && c.active == 0 &&
            (c.posted == count || block.timestamp > c.executionEnd), "missions still open");
        c.phase = Phase.Closed; emit CampaignClosed(id, c.reserve, c.supply);
    }
    function reclaim(uint256 id) external nonReentrant returns (uint256 amount) {
        Campaign storage c = campaigns[id]; uint256 count = lots[id][msg.sender];
        require(c.phase == Phase.Closed && count > 0, "no capital claim");
        amount = c.reserve * count / c.supply;
        lots[id][msg.sender] = 0; c.supply -= uint32(count); c.reserve -= amount;
        if (amount > 0) token.safeTransfer(msg.sender, amount);
        emit CapitalReturned(id, msg.sender, amount);
    }
}

project/contracts/ascension/AscensionRis.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./NovaSeed.sol";
import "./AscensionToken.sol";

interface IAscensionJobBinding {
    function oracle() external view returns (address);
    function access() external view returns (address);
}

/// @notice Staked, live-ENS validators attest to a specific seed owner and immutable plan; approvals expire.
contract AscensionRiskOracle is AscensionToken, Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;
    struct Round { uint64 number; uint64 until; uint16 yes; uint16 no; address owner; }
    AscensionAccess public immutable access;
    NovaSeed public immutable seed;
    uint256 public immutable minimumStake;
    uint16 public immutable quorum;
    uint16 public immutable maximumRiskBps;
    address public marketplace;
    mapping(address => uint256) public stake;
    mapping(address => uint64) public lockedUntil;
    mapping(address => mapping(address => uint64)) public jobAvailability;
    mapping(address => uint32) public jobCapacity;
    mapping(address => uint32) public activeJobs;
    mapping(uint256 => Round) public rounds;
    mapping(uint256 => mapping(uint64 => mapping(address => bool))) public voted;
    mapping(uint256 => mapping(uint64 => address[])) private supporters;
    event ReviewOpened(uint256 indexed seedId, uint64 round, address owner, uint64 until);
    event RiskAttested(uint256 indexed seedId, uint64 round, address indexed validator,
        uint16 riskBps, bool admitted, bytes32 evidenceHash);
    event StakeChanged(address indexed validator, uint256 balance);
    event JobAvailability(address indexed validator, address indexed business, uint64 until, uint32 capacity);
    event MarketplaceBound(address indexed marketplace);

    constructor(AscensionAccess access_, NovaSeed seed_, uint256 minimum_, uint16 quorum_, uint16 risk_,
        address governor) Ownable(governor) {
        require(minimum_ > 0 && quorum_ >= 2 && quorum_ <= 15 && risk_ <= 10000, "oracle parameters");
        require(address(seed_.access()) == address(access_), "seed/access mismatch");
        access = access_; seed = seed_; minimumStake = minimum_; quorum = quorum_; maximumRiskBps = risk_;
    }
    function bindMarketplace(address value) external onlyOwner {
        require(marketplace == address(0) && value.code.length > 0, "binding is one-time");
        require(IAscensionJobBinding(value).oracle() == address(this) &&
            IAscensionJobBinding(value).access() == address(access), "marketplace/oracle mismatch");
        marketplace = value;
        emit MarketplaceBound(value);
    }
    function deposit(uint256 amount) external nonReentrant {
        require(amount > 0 && access.eligible(msg.sender, AscensionAccess.Role.Validator), "validator identity");
        _receive(msg.sender, amount); stake[msg.sender] += amount;
        emit StakeChanged(msg.sender, stake[msg.sender]);
    }
    function withdraw(uint256 amount) external nonReentrant {
        require(block.timestamp > lockedUntil[msg.sender] && amount > 0 && amount <= stake[msg.sender], "locked stake");
        stake[msg.sender] -= amount; token.safeTransfer(msg.sender, amount);
        emit StakeChanged(msg.sender, stake[msg.sender]);
    }
    function isValidator(address account) public view returns (bool) {
        return stake[account] >= minimumStake && access.eligible(account, AscensionAccess.Role.Validator);
    }
    function setJobAvailability(address business, uint64 until, uint32 capacity) external {
        require(business != address(0) && (until == 0 || (until > block.timestamp &&
            until <= block.timestamp + 120 days)) && capacity <= 128, "availability bounds");
        jobAvailability[msg.sender][business] = until; jobCapacity[msg.sender] = capacity;
        emit JobAvailability(msg.sender, business, until, capacity);
    }
    function releaseFromJob(address validator) external {
        require(msg.sender == marketplace && activeJobs[validator] > 0, "marketplace lock required");
        activeJobs[validator]--;
    }
    function lockForJob(address validator, address business, uint64 until) external {
        require(msg.sender == marketplace, "marketplace only");
        require(isValidator(validator) && until > block.timestamp && until <= block.timestamp + 120 days, "validator lock");
        require(jobAvailability[validator][business] >= until && activeJobs[validator] < jobCapacity[validator],
            "review capacity not reserved");
        activeJobs[validator]++;
        if (until > lockedUntil[validator]) lockedUntil[validator] = until;
    }
    function openReview(uint256 id) external {
        require(seed.ownerOf(id) == msg.sender && access.eligible(msg.sender, AscensionAccess.Role.Business), "seed owner");
        Round storage r = rounds[id];
        require(r.until < block.timestamp, "review still active");
        r.number++; r.until = uint64(block.timestamp + 7 days); r.yes = 0; r.no = 0; r.owner = msg.sender;
        emit ReviewOpened(id, r.number, msg.sender, r.until);
    }
    function attest(uint256 id, uint16 riskBps, bool policyApproved, bytes32 evidenceHash) external {
        Round storage r = rounds[id];
        require(r.until > block.timestamp && r.owner == seed.ownerOf(id), "review expired or transferred");
        require(r.yes < quorum && r.no < quorum, "review decided");
        require(isValidator(msg.sender) && msg.sender != r.owner && msg.sender != seed.creatorOf(id), "independent validator");
        require(!voted[id][r.number][msg.sender], "duplicate vote");
        require(riskBps <= 10000 && evidenceHash != bytes32(0), "attestation required");
        voted[id][r.number][msg.sender] = true;
        if (r.until > lockedUntil[msg.sender]) lockedUntil[msg.sender] = r.until;
        bool yes = policyApproved && riskBps <= maximumRiskBps;
        if (yes) { r.yes++; supporters[id][r.number].push(msg.sender); } else { r.no++; }
        emit RiskAttested(id, r.number, msg.sender, riskBps, yes, evidenceHash);
    }
    function green(uint256 id) external view returns (bool) {
        Round storage r = rounds[id];
        if (r.until <= block.timestamp || r.yes < quorum || r.owner != seed.ownerOf(id) ||
            !access.eligible(r.owner, AscensionAccess.Role.Business)) return false;
        address[] storage signers = supporters[id][r.number];
        for (uint256 i; i < signers.length; ++i) if (!isValidator(signers[i])) return false;
        return true;
    }
}

project/contracts/ascension/AscensionTok.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "../v2/Constants.sol";

interface IAscensionBurn { function burn(uint256 amount) external; }

/// @notice Canonical token only; reject fee-on-transfer deposits and verify actual supply destruction.
abstract contract AscensionToken {
    using SafeERC20 for IERC20;
    IERC20 public constant token = IERC20(Constants.AGIALPHA);
    constructor() {
        require(address(token).code.length > 0, "AGIALPHA contract required");
        require(IERC20Metadata(address(token)).decimals() == 18, "wrong decimals");
    }
    function _receive(address from, uint256 amount) internal {
        uint256 before_ = token.balanceOf(address(this));
        token.safeTransferFrom(from, address(this), amount);
        require(token.balanceOf(address(this)) == before_ + amount, "non-exact deposit");
    }
    function _burn(uint256 amount) internal {
        if (amount == 0) return;
        uint256 before_ = token.totalSupply();
        IAscensionBurn(address(token)).burn(amount);
        require(token.totalSupply() == before_ - amount, "supply not burned");
    }
}

project/contracts/ascension/NovaSeed.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "./AscensionAccess.sol";

/// @notice Transferable ERC-721 binding an encrypted capsule, immutable FusionPlan and optional successor lineage.
contract NovaSeed is ERC721URIStorage {
    struct Genome {
        bytes32 capsuleHash;
        bytes32 planRoot;
        bytes32 evidenceHash;
        uint256 parent;
        uint32 jobs;
        address creator;
    }
    AscensionAccess public immutable access;
    uint256 public nextId;
    mapping(uint256 => Genome) public genomes;
    event SeedSealed(uint256 indexed seedId, address indexed creator, bytes32 capsuleHash,
        bytes32 planRoot, uint256 parent, bytes32 evidenceHash);

    constructor(AscensionAccess access_) ERC721("Alpha AGI Nova-Seeds", "NOVA") { access = access_; }

    function seal(bytes32 capsuleHash, bytes32 planRoot, uint32 jobs, string calldata metadataURI,
        uint256 parent, bytes32 evidenceHash) external returns (uint256 id) {
        require(access.eligible(msg.sender, AscensionAccess.Role.Business), "business identity");
        require(capsuleHash != bytes32(0) && planRoot != bytes32(0) && evidenceHash != bytes32(0), "empty commitment");
        require(jobs > 0 && jobs <= 128, "job bound");
        require(bytes(metadataURI).length > 0 && bytes(metadataURI).length <= 512, "metadata URI");
        if (parent != 0) require(ownerOf(parent) == msg.sender, "parent ownership");
        id = ++nextId;
        genomes[id] = Genome(capsuleHash, planRoot, evidenceHash, parent, jobs, msg.sender);
        // State and URI are complete before an ERC-721 receiver can be invoked.
        _mint(msg.sender, id);
        _setTokenURI(id, metadataURI);
        emit SeedSealed(id, msg.sender, capsuleHash, planRoot, parent, evidenceHash);
    }
    function plan(uint256 id) external view returns (bytes32 root, uint32 count) {
        ownerOf(id);
        Genome storage genome = genomes[id];
        return (genome.planRoot, genome.jobs);
    }
    function creatorOf(uint256 id) external view returns (address) { ownerOf(id); return genomes[id].creator; }
}

